index.css:
.attachment-chatui {
    height: 500px;
    width: 40%;
    margin: 0 auto;
    display: flex;
    flex-direction: row;
    gap: 50px;
}
.attachment-chatui .chat_user_avatar {
    background-image: url('https://ej2.syncfusion.com/react/demos/src/chat-ui/images/paul_wilson.png');
    background-color: unset;
} 
.attachment-chatui .emptyChatText {
    font-size: 16px;
    font-style: italic;
}
.attachment-chatui .emptychat-content {
    display: flex;
    flex-direction: column;
    justify-content: center;
    text-align: center;
    align-items: center;
    padding: 10px;
}
.attachment-chatui .chat-text-content {
    display: flex;
    align-items: center;
}
.attachment-chatui .emptyChatText {
    font-size: 14px;
    font-weight: 500;
    margin-left: 10px;
}
.attachment-chatui .emptyChatMessage {
    font-size: 14px;
    text-align: center;
}
@media only screen and (max-width: 850px) {
    .attachment-chatui {
        flex-direction: column;
        height: 500px;
        width: 70%;
    }
}

index.js:
import { createRoot } from 'react-dom/client';
import './index.css';
import { ChatUIComponent } from '@syncfusion/ej2-react-interactive-chat';
import * as React from 'react';
import { useEffect, useRef, useState } from 'react';


const Attachments = () => {
    const [user] = useState({
        id: 'user1',
        user: 'Paul Wilson',
        avatarUrl: 'https://ej2.syncfusion.com/react/demos/src/chat-ui/images/paul_wilson.png'
    });
    // The chat message history state (for controlled chat)
    const [messages, setMessages] = useState([]);
    const chatRef = useRef(null);
    // Toolbar setup, with a single Clear Chat button
    const headerToolbar = {
        items: [
            {
                iconCss: 'e-icons e-refresh',
                align: 'Right',
                tooltip: 'Clear Chat'
            }
        ],
        itemClicked: () => {
            chatRef.current.messages = [];
        }
    };
    return (<div className="control-pane">
      <div className="control-section chat-ui">
        <div className="attachment-chatui">
          <ChatUIComponent ref={chatRef} headerText="Paul Wilson (You)" headerIconCss="chat_user_avatar" user={user} messages={messages} emptyChatTemplate={`
              <div class="emptychat-content">
                <div class="chat-text-content">
                  <h5><span class="e-icons e-multiple-comment"></span></h5>
                  <div class="emptyChatText">No conversations yet.</div>
                </div>
                <div class="emptyChatMessage" >Type to begin or attach images, videos or files.</div>
              </div>
            `} enableAttachments={true} attachmentSettings={{
            saveUrl: 'https://services.syncfusion.com/react/production/api/FileUploader/Save',
            removeUrl: 'https://services.syncfusion.com/react/production/api/FileUploader/Save'
        }} headerToolbar={headerToolbar}/>
        </div>
      </div>
    </div>);
};
export default Attachments;

const root = createRoot(document.getElementById('sample'));
root.render(<Attachments />);
